def fill_phone_numbers(apps, schema_editor):
    # Existing phone reports get their number in the standard form, so "0788..." and
    # "+250788..." reports of the same number are counted and removed together.
    CommunityReport = apps.get_model("reporting", "CommunityReport")
    for report in CommunityReport.objects.filter(report_type="PHONE"):
        report.phone_number = reporting.models.phone_key(report.content)
        report.save(update_fields=["phone_number"])


